class Base {
public:
    virtual ~Base() { cout << "~Base\n"; }   // VIRTUAL dtor: fix
};
class Derived : public Base {
    int *big;
public:
    Derived()  { big = new int[1000000]; }
    ~Derived() { delete[] big; cout << "~Derived\n"; }
};

int main() {
    Base *b = new Derived();
    delete b;   // virtual dtor -> BOTH destructors run, no leak
}

