class Base:
    pass

class Derived(Base):
    def __init__(self):
        self.big = list(range(1_000_000))   # resource-ish payload
    def __del__(self):
        print('~Derived cleanup')           # finalizer (best-effort)

b = Derived()
del b                       # GC decides when __del__ runs - not deterministic like C++
# Interview translation: RAII/guaranteed cleanup in Python comes from
