class MinStack:
    def __init__(self):
        self.st = []                      # (value, min_so_far) pairs
    def push(self, x):
        mn = x if not self.st else min(x, self.st[-1][1])
        self.st.append((x, mn))
    def pop(self):     self.st.pop()
    def top(self):     return self.st[-1][0]
    def getMin(self):  return self.st[-1][1]
